function renderChart(values){const w=600,h=160,p=12,min=Math.min(...values)-2,max=Math.max(...values)+2;const pts=values.map((v,i)=>[p+i*(w-p*2)/(values.length-1),h-p-(v-min)*(h-p*2)/(max-min)]);const poly=pts.map(p=>p.join(',')).join(' ');const area=`${p},${h-p} ${poly} ${w-p},${h-p}`;els.indexChart.innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#f26d67" stop-opacity=".22"/><stop offset="1" stop-color="#f26d67" stop-opacity="0"/></linearGradient></defs>${[30,70,110,150].map(y=>`<line class="chart-gridline" x1="0" y1="${y}" x2="600" y2="${y}"/>`).join('')}<polygon class="chart-area" points="${area}"/><polyline class="chart-line" points="${poly}"/>${pts.map((p,i)=>`<circle class="chart-dot ${i===pts.length-1?'current':''}" cx="${p[0]}" cy="${p[1]}" r="${i===pts.length-1?5:3}"/>`).join('')}</svg>`}
function renderBars(values){const max=Math.max(...values);els.volumeChart.innerHTML=values.map(v=>{const h=Math.round(v/max*100);return `<div class="bar-wrap" data-value="${v}건" style="--h:${h}%"><i style="height:${h}%"></i></div>`}).join('')}
function renderRank(target,data){const nums=data.map(x=>parseFloat(String(x[2]).replace(/,/g,''))) ;const max=Math.max(...nums);target.innerHTML=data.map((r,i)=>`<div class="rank-row"><span class="num">${String(i+1).padStart(2,'0')}</span><span class="rank-name"><strong>${r[0]}</strong><small>${r[1]}</small></span><span class="rank-bar"><i style="width:${Math.max(18,nums[i]/max*100)}%"></i></span><span class="rank-price">${r[2]}</span></div>`).join('')}
function renderDeal(key,announce=false){currentDeal=key;const d=datasets[key];els.asOf.textContent=d.asOf;document.querySelector('.asof small').textContent=d.asOfSub;els.marketSummary.textContent=d.summary;els.kpiGrid.innerHTML=d.kpis.map((k,i)=>`<article class="kpi" style="--kpi-color:${['#ffe0dc','#dceef2','#e5eccf','#eee4d6'][i]}"><span class="kpi-label">${k[0]}</span><div class="kpi-value"><strong>${k[1]}</strong><span>${k[2]}</span></div><div class="kpi-meta"><b class="${k[5]}">${k[3]}</b>${k[4]}</div></article>`).join('');els.indexTitle.textContent=`아파트 ${d.label} 가격지수`;els.indexValue.textContent=d.indexValue;els.indexDelta.textContent=d.indexDelta;els.indexDelta.className=d.indexDelta.startsWith('-')?'down':'up';renderChart(d.index);els.volumeTitle.textContent=`월별 ${d.label} 거래량`;els.volumeBadge.textContent=d.volumeBadge;els.volumeBadge.style.background=d.volumeBadge.includes('-')?'var(--blue-soft)':'var(--coral-soft)';els.volumeBadge.style.color=d.volumeBadge.includes('-')?'#2788ad':'#c94d48';els.volumeValue.textContent=d.volumeValue;els.volumeSub.textContent=d.volumeSub;els.volumeNote.innerHTML=`<span>활발</span> ${d.volumeNote}`;renderBars(d.volume);els.gauge.style.setProperty('--score',d.gauge);els.gaugeValue.textContent=d.gauge;els.gauge.querySelector('span').textContent=d.gaugeLabel;els.gaugeHeadline.textContent=d.gaugeHeadline;els.gaugeText.textContent=d.gaugeText;els.tradeRankTitle.textContent=d.tradeTitle;els.unitRankTitle.textContent=d.unitTitle;els.tradeRankUnit.textContent=d.tradeUnit;els.unitRankUnit.textContent=d.unitUnit;renderRank(els.tradeRank,d.trade);renderRank(els.unitRank,d.unit);document.querySelectorAll('[data-deal]').forEach(btn=>{const active=btn.dataset.deal===key;btn.classList.toggle('active',active);btn.setAttribute('aria-pressed',String(active))});updateContext();if(announce)showToast(`${d.label} 데이터로 전환했습니다.`)}
function updateContext(){els.contextLabel.textContent=`${regionNames[document.querySelector('#regionSelect').value]} · ${datasets[currentDeal].label}`}
function renderLocation(key){const d=locationData[key];document.querySelector('#detailKicker').textContent=d.kicker;document.querySelector('#detailTitle').textContent=d.title;document.querySelector('#detailScore').textContent=d.score;document.querySelector('#detailSummary').textContent=d.summary;document.querySelector('#areaChips').innerHTML=d.areas.map(x=>`<span>${x}</span>`).join('');document.querySelector('#scoreBars').innerHTML=d.bars.map(x=>`<div class="score-row"><span>${x[0]}</span><div><i style="width:${x[1]}%"></i></div><b>${x[1]}</b></div>`).join('');document.querySelector('#detailBullets').innerHTML=d.bullets.map(x=>`<li>${x}</li>`).join('');document.querySelector('#detailCaution').textContent=d.caution;document.querySelectorAll('.location-tab').forEach(btn=>{const active=btn.dataset.location===key;btn.classList.toggle('active',active);btn.setAttribute('aria-selected',String(active))})}
let toastTimer;function showToast(msg){clearTimeout(toastTimer);els.toast.textContent=msg;els.toast.classList.add('show');toastTimer=setTimeout(()=>els.toast.classList.remove('show'),2200)}
document.querySelectorAll('[data-deal]').forEach(btn=>btn.addEventListener('click',()=>renderDeal(btn.dataset.deal,true)));
document.querySelectorAll('.location-tab').forEach(btn=>btn.addEventListener('click',()=>renderLocation(btn.dataset.location)));
document.querySelector('#regionSelect').addEventListener('change',e=>{updateContext();showToast(`${regionNames[e.target.value]} 생활권으로 범위를 바꿨습니다.`)});
document.querySelector('#dateSelect').addEventListener('change',e=>showToast(e.target.value==='latest'?'최신 집계로 돌아왔습니다.':`${e.target.options[e.target.selectedIndex].text} 비교 화면입니다.`));
document.querySelector('#resetBtn').addEventListener('click',()=>{document.querySelector('#regionSelect').value='all';document.querySelector('#dateSelect').value='latest';renderDeal('sale');showToast('필터를 초기화했습니다.')});
const methodPanel=document.querySelector('#methodPanel');function toggleMethod(show){methodPanel.hidden=!show;document.querySelector('#methodBtn').setAttribute('aria-expanded',String(show))}document.querySelector('#methodBtn').addEventListener('click',()=>toggleMethod(methodPanel.hidden));document.querySelector('#closeMethod').addEventListener('click',()=>toggleMethod(false));document.querySelector('#closeMethodLink').addEventListener('click',()=>toggleMethod(false));
const sections=[...document.querySelectorAll('main section[id]')];const navLinks=[...document.querySelectorAll('.nav a')];const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){navLinks.forEach(a=>a.classList.toggle('active',a.getAttribute('href')===`#${entry.target.id}`))}}),{rootMargin:'-45% 0px -50%'});sections.forEach(s=>observer.observe(s));
renderDeal('sale');renderLocation('school');
